SELECT n_name, SUM(ol_amount) AS revenue FROM tpcch.customer, order_view, tpcch.orderline, tpcch.stock, tpcch.supplier, tpcch.nation, tpcch.region WHERE c_id = o_c_id AND c_w_id = o_w_id AND c_d_id = o_d_id AND ol_o_id = o_id AND ol_w_id = o_w_id AND ol_d_id = o_d_id AND ol_w_id = s_w_id AND ol_i_id = s_i_id AND s_su_suppkey = su_suppkey AND c_n_nationkey = su_nationkey AND su_nationkey = n_nationkey AND n_regionkey = r_regionkey AND r_name = 'EUROPE' AND o_entry_d >= '2007-01-02 00:00:00.000000' GROUP BY n_name ORDER BY revenue DESC;
